class TestSetAccessTokenValidation:
    @pytest.mark.parametrize(
        "token",
        ["abc\r\nInjected: yes", "abc\ndef", "abc\x00def", "abc\x7fdef", "töken"],
    )
    def test_a_token_outside_printable_ascii_is_rejected(self, token: str) -> None:
        auth = _create_authenticator()
        auth.set_access_token("kept")

        with pytest.raises(ValueError) as excinfo:
            auth.set_access_token(token)

        assert type(excinfo.value) is ValueError
        assert str(excinfo.value) == (
            "Access token must contain only printable ASCII characters (RFC 7230 §3.2.6)"
        )
        assert auth.get_auth_headers() == {"Authorization": "Bearer kept"}

    def test_a_tab_is_allowed_inside_a_token(self) -> None:
        auth = _create_authenticator()

        auth.set_access_token("a\tb")

        assert auth.get_auth_headers() == {"Authorization": "Bearer a\tb"}


